  { c:"fish", n:"Balık ekmek tekneleri", a:"Eminönü, Galata Köprüsü altı", p:"150–200 ₺", d:"Ekmek arası ızgara uskumru, yanında şalgam. Turist ritüeli; köprü altındaki restoranlardan kaçının (3 kat fiyat). Kart geçer.", q:"Eminönü balık ekmek" },
  { c:"fish", n:"Ada balığı: Milto, Ali Baba", a:"Büyükada, iskelenin solu", p:"800–1.200 ₺", d:"Milto 1923'ten beri; rıhtımda masa, meze, ızgara balık. Balık kiloyla: <b>sipariş vermeden fiyat sorun</b>, hesabı menüyle karşılaştırın. <b>Paz 13:45.</b>", q:"Milto Restaurant Büyükada", day:"Paz" },
  { c:"bfast", n:"Van Kahvaltı Evi", a:"Cihangir, Defterdar Yokuşu 52A", p:"500–700 ₺", d:"İstanbul'un en meşhur Türk kahvaltısı (Van usulü): 20'den fazla küçük tabak, otlu peynir, ballı kaymak, menemen, murtuğa. Hafta sonu 30 dk sıra; otelden taksi 150 ₺. Pazartesi sabah seçeneği.", q:"Van Kahvaltı Evi Cihangir" },
  { c:"bfast", n:"Namlı Gurme", a:"Karaköy, Rıhtım Cd.", p:"400–600 ₺", d:"Şarküteri + kahvaltı: 100 çeşit peynir, pastırma, zeytin; serpme kahvaltı. Galata ve İstanbul Modern'in yanı, yağmurda iyi.", q:"Namlı Gurme Karaköy" },
  { c:"bfast", n:"Mandabatmaz", a:"Beyoğlu, Olivia Geçidi", p:"Kahve 80 ₺", d:"1967'den beri İstanbul'un en koyu Türk kahvesi ('manda batmaz'). İstiklal'in yanında 4 masalık minik dükkân. Cmt İstiklal'de.", q:"Mandabatmaz Beyoğlu", day:"Cmt" },
  { c:"bfast", n:"Fazıl Bey'in Türk Kahvesi", a:"Kadıköy, Serasker Cd.", p:"Kahve 90 ₺", d:"1923'ten beri Kadıköy çarşısında taze çekilmiş Türk kahvesi, damla sakızlı versiyonu da var. Per Kadıköy'de.", q:"Fazıl Bey Türk Kahvesi Kadıköy", day:"Per" },
  { c:"sweet", n:"Karaköy Güllüoğlu", a:"Karaköy, Rıhtım Cd.", p:"Baklava 150–200 ₺/porsiyon", d:"1949'dan beri Antepli Güllü ailesi: fıstıklı baklava, şöbiyet, kaymaklı. İstanbul'un en meşhur baklavası; hediye kutusu (Pzt alın, 2 gün dayanır). <b>Cmt 14:15.</b>", q:"Karaköy Güllüoğlu", u:"https://www.karakoygulluoglu.com/", day:"Cmt" },
  { c:"sweet", n:"Hafız Mustafa 1864", a:"Sirkeci, Sultanahmet, Eminönü (çok şube)", p:"Baklava 180 ₺, lokum kg 1.500 ₺+", d:"1864'ten beri turistlerin gözde tatlıcısı: baklava, lokum, sütlaç, Osmanlı kahvesi. Güllüoğlu'ndan pahalı ama hediye kutuları güzel. <b>Pzt sabah.</b>", q:"Hafız Mustafa 1864 Sirkeci", day:"Pzt" },
  { c:"sweet", n:"Ali Muhiddin Hacı Bekir", a:"Eminönü Hamidiye Cd. 83; İstiklal", p:"Lokum kg 1.000–1.400 ₺", d:"1777'den beri, lokumu icat ettiği kabul edilen aile (Osmanlı sarayının şekercisi). Fıstıklı ve güllü lokum, akide şekeri. Hediye için Hafız Mustafa'dan daha otantik ve ucuz.", q:"Ali Muhiddin Hacı Bekir Eminönü", u:"https://www.hacibekir.com/" },
  { c:"sweet", n:"Saray Muhallebicisi", a:"İstiklal, Taksim, çok şube", p:"Tatlı 150–250 ₺", d:"1935'ten beri sütlü tatlı klasiği: tavuk göğsü, kazandibi, sütlaç, fırın sütlaç. 24 saat açık şubeleri var.", q:"Saray Muhallebicisi İstiklal" },
  { c:"sweet", n:"Vefa Bozacısı", a:"Süleymaniye'nin yanı", p:"Boza 60 ₺", d:"1876'dan beri fermente darı bozası, leblebiyle. Atatürk'ün bardağı. <b>Paz 16:50.</b>", q:"Vefa Bozacısı", day:"Paz" },
  { c:"sweet", n:"Dondurmacı Ali Usta", a:"Moda, Moda Cd. 264", p:"Dondurma 100–150 ₺", d:"1969'dan beri Moda'nın efsane dondurmacısı: 30'dan fazla çeşit, şam fıstıklı, vişneli; sıra olur ama hızlı. <b>Per 17:15.</b>", q:"Dondurmacı Ali Usta Moda", day:"Per" },
  { c:"sweet", n:"Baylan", a:"Kadıköy, Muvakkithane Cd. 9", p:"Kup griye 300 ₺", d:"1923'ten beri Rum ailenin pastanesi: kup griye (karamel, dondurma, bademli krema). Kadıköy çarşısının ortasında sakin bir köşe.", q:"Baylan Pastanesi Kadıköy", day:"Per" },
  { c:"sweet", n:"Şampiyon Kokoreç", a:"Beyoğlu, Balık Pazarı", p:"200–300 ₺", d:"1960'lardan beri ekmek arası kokoreç, midye tava. İstiklal sokak lezzeti klasiği; cesaret ister, lezzetlidir.", q:"Şampiyon Kokoreç Beyoğlu" },
  { c:"sweet", n:"Simit, midye, kestane, mısır", a:"Her sokakta", p:"Simit 25 ₺, midye 20 ₺/adet, kestane 150 ₺", d:"Sabah kırmızı arabalardan simit; midye dolma Kadıköy ve İstiklal'de; kestane ve mısır Ekim'de başlar. Kestane Beyoğlu'nda iyidir.", q:"Istiklal Caddesi" }
